"""Numerically verify the bridge identity sum_g|Fix(g)| = sum_x|Stab(x)|
and the two-methods-agree formula for GL(n,2) acting on all Boolean functions."""
from __future__ import annotations
from itertools import product
from math import prod
from typing import Callable, List, Sequence, Tuple

Matrix = Tuple[Tuple[int, ...], ...]

def is_invertible_f2(mat: Matrix, n: int) -> bool:
    rows: List[int] = [sum((mat[i][j] & 1) << j for j in range(n)) for i in range(n)]
    rank = 0
    for col in range(n):
        pivot = next((r for r in range(rank, n) if (rows[r] >> col) & 1), None)
        if pivot is None:
            continue
        rows[rank], rows[pivot] = rows[pivot], rows[rank]
        for r in range(n):
            if r != rank and (rows[r] >> col) & 1:
                rows[r] ^= rows[rank]
        rank += 1
    return rank == n

def gl(n: int) -> List[Matrix]:
    out: List[Matrix] = []
    for flat in product((0, 1), repeat=n * n):
        m = tuple(tuple(flat[i * n + j] for j in range(n)) for i in range(n))
        if is_invertible_f2(m, n):
            out.append(m)
    return out

def mat_vec(mat: Matrix, v: int, n: int) -> int:
    o = 0
    for i in range(n):
        b = 0
        for j in range(n):
            b ^= mat[i][j] & ((v >> j) & 1)
        o |= (b & 1) << i
    return o

def mat_mul(a: Matrix, b: Matrix, n: int) -> Matrix:
    return tuple(tuple(sum(a[i][k] & b[k][j] for k in range(n)) & 1
                       for j in range(n)) for i in range(n))

def report(n: int) -> None:
    group = gl(n)
    idn = tuple(tuple(1 if i == j else 0 for j in range(n)) for i in range(n))
    inv = {g: next(h for h in group if mat_mul(g, h, n) == idn) for g in group}
    funcs = list(range(1 << (1 << n)))
    def act(g: Matrix, f: int) -> int:
        gi = inv[g]
        r = 0
        for v in range(1 << n):
            r |= ((f >> mat_vec(gi, v, n)) & 1) << v
        return r
    burnside = sum(sum(1 for f in funcs if act(g, f) == f) for g in group)
    stab = sum(sum(1 for g in group if act(g, f) == f) for f in funcs)
    orbits = burnside // len(group)
    print(f"n={n}: |G|={len(group)}, burnside={burnside}, stab={stab}, "
          f"bridge={burnside == stab}, orbits={orbits}")

if __name__ == "__main__":
    for n in (2, 3):
        report(n)

"""Structural read-off of the classification number 3,691,560 by factorization."""
from __future__ import annotations
from math import comb, isqrt, prod
from typing import Dict

def factorize(n: int) -> Dict[int, int]:
    f: Dict[int, int] = {}
    m, d = n, 2
    while d * d <= m:
        while m % d == 0:
            f[d] = f.get(d, 0) + 1
            m //= d
        d += 1
    if m > 1:
        f[m] = f.get(m, 0) + 1
    return f

def is_prime(n: int) -> bool:
    return n >= 2 and all(n % d for d in range(2, isqrt(n) + 1))

def gl_order(n: int) -> int:
    return prod((1 << n) - (1 << k) for k in range(n))

if __name__ == "__main__":
    N = 3_691_560
    print("orbit count                :", N)
    print("|GL(10,2)|                  :", gl_order(10))
    print("dim cubic layer C(10,3)     :", comb(10, 3))
    fac = factorize(N)
    print("factorization              :",
          " * ".join(f"{p}^{e}" if e > 1 else str(p) for p, e in fac.items()))
    print("equals 120 * 30763         :", N == 120 * 30763)
    print("120 = C(10,3) = 5!         :", 120 == comb(10, 3) == 120)
    print("30763 is prime             :", is_prime(30763))

"""The division principle: a fixed-point sum N*|G| certifies exactly N orbits."""
from __future__ import annotations
from itertools import permutations
from typing import Callable, List, Sequence

def burnside_fixed_sum(group: Sequence, domain: Sequence,
                       act: Callable) -> int:
    return sum(sum(1 for x in domain if act(g, x) == x) for g in group)

def division_principle(fixed_sum: int, group_order: int) -> int:
    if group_order <= 0:
        raise ValueError("group order must be positive")
    if fixed_sum % group_order:
        raise ValueError("group order does not divide the fixed-point sum")
    return fixed_sum // group_order

def orbit_count_enum(group: Sequence, domain: Sequence, act: Callable) -> int:
    seen, orbits = set(), 0
    for x in domain:
        if x in seen:
            continue
        orbits += 1
        seen |= {act(g, x) for g in group}
    return orbits

if __name__ == "__main__":
    # S_n acting on n points: always transitive, so exactly 1 orbit.
    for n in range(2, 7):
        G = list(permutations(range(n)))
        X = list(range(n))
        act = lambda g, x: g[x]
        s = burnside_fixed_sum(G, X, act)
        N = division_principle(s, len(G))
        print(f"S_{n} on {n} points: sum|Fix|={s}, |G|={len(G)}, "
              f"orbits(div)={N}, orbits(enum)={orbit_count_enum(G, X, act)}")

