function ORBIT_COUNT_BURNSIDE(G, X, act):
    fixed_sum <- 0
    for g in G:
        for x in X:
            if act(g, x) == x: fixed_sum <- fixed_sum + 1
    assert fixed_sum mod |G| == 0
    return fixed_sum / |G|

function BRIDGE_CHECK(G, X, act):
    burnside <- sum over g in G of |{x in X : act(g,x)=x}|
    stab     <- sum over x in X of |{g in G : act(g,x)=x}|
    return (burnside, stab, burnside == stab)

function ENUMERATE_GL_F2(n):
