    for each 0/1 matrix M of size n x n:
        if F2_RANK(M) == n: append M to result
    return result

function FACTOR_AND_CERTIFY(n):
    factors <- {}
    d <- 2
    while d*d <= n:
        while n mod d == 0: factors[d]++, n <- n/d
        d <- d + 1
    if n > 1: factors[n]++
    p <- max(factors)
    prime <- for all k in [2, sqrt(p)]: p mod k != 0
    return factors, p, prime

